"Hopkinsville","containedInPlace":{"@type":"State","name":"Kentucky"}},{"@type":"City","name":"Pikeville","containedInPlace":{"@type":"State","name":"Kentucky"}},{"@type":"City","name":"Ashland","containedInPlace":{"@type":"State","name":"Kentucky"}}],"knowsAbout":["Insurance appraisal","Appraisal clause","Amount of loss","Property claim estimating","Hail and wind damage","Ice storm damage"],"hasOfferCatalog":{"@type":"OfferCatalog","name":"Insurance appraisal services","itemListElement":[{"@type":"Offer","itemOffered":{"@type":"Service","name":"Appraisal Clause Representation","url":"https://kentuckyinsuranceappraiser.com/insurance-appraisal/party-appraiser-representation/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Homeowners Insurance Appraisal","url":"https://kentuckyinsuranceappraiser.com/insurance-appraisal/home-insurance-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Commercial & HOA Appraisal","url":"https://kentuckyinsuranceappraiser.com/insurance-appraisal/commercial-hoa-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Roof & Hail Damage Appraisal","url":"https://kentuckyinsuranceappraiser.com/insurance-appraisal/roof-hail-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Tornado & Wind Damage Appraisal","url":"https://kentuckyinsuranceappraiser.com/insurance-appraisal/tornado-wind-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Water Damage Appraisal","url":"https://kentuckyinsuranceappraiser.com/insurance-appraisal/water-damage-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Fire & Smoke Damage Appraisal","url":"https://kentuckyinsuranceappraiser.com/insurance-appraisal/fire-smoke-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Ice Storm & Freeze Damage Appraisal","url":"https://kentuckyinsuranceappraiser.com/insurance-appraisal/ice-storm-freeze-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Farm, Barn & Equine Property Appraisal","url":"https://kentuckyinsuranceappraiser.com/insurance-appraisal/farm-equine-property-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Insurance Estimate Review","url":"https://kentuckyinsuranceappraiser.com/insurance-appraisal/second-look-estimate-review/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Umpire Services","url":"https://kentuckyinsuranceappraiser.com/insurance-appraisal/neutral-umpire-services/"}}]},"openingHoursSpecification":[{"@type":"OpeningHoursSpecification","dayOfWeek":["Monday","Tuesday","Wednesday","Thursday","Friday"],"opens":"08:00","closes":"18:00"}]},{"@type":"WebSite","@id":"https://kentuckyinsuranceappraiser.com/#website","url":"https://kentuckyinsuranceappraiser.com/","name":"Kentucky Insurance Appraiser","publisher":{"@id":"https://kentuckyinsuranceappraiser.com/#business"},"inLanguage":"en-US"},{"@type":"WebPage","@id":"https://kentuckyinsuranceappraiser.com/insurance-appraisal-questions/#webpage","url":"https://kentuckyinsuranceappraiser.com/insurance-appraisal-questions/","name":"Insurance Appraisal FAQ | Kentucky Owners’ Questions","description":"Answers to common Kentucky insurance appraisal questions: how it works, costs and fees, timing and deadlines, state specifics and working with us.","inLanguage":"en-US","isPartOf":{"@id":"https://kentuckyinsuranceappraiser.com/#website"},"about":{"@id":"https://kentuckyinsuranceappraiser.com/#business"},"publisher":{"@id":"https://kentuckyinsuranceappraiser.com/#business"},"dateModified":"2026-11-12","breadcrumb":{"@id":"https://kentuckyinsuranceappraiser.com/insurance-appraisal-questions/#breadcrumb"},"primaryImageOfPage":{"@type":"ImageObject","@id":"https://kentuckyinsuranceappraiser.com/insurance-appraisal-questions/#primaryimage","url":"https://kentuckyinsuranceappraiser.com/assets/img/photos/living-room.webp","width":1024,"height":768,"caption":"Living room with a stone fireplace and white armchairs"},"mainEntity":{"@id":"https://kentuckyinsuranceappraiser.com/insurance-appraisal-questions/#faq"}},{"@type":"BreadcrumbList","itemListElement":[{"@type":"ListItem","position":1,"name":"Home","item":"https://kentuckyinsuranceappraiser.com/"},{"@type":"ListItem","position":2,"name":"Appraisal questions","item":"https://kentuckyinsuranceappraiser.com/insurance-appraisal-questions/"}],"@id":"https://kentuckyinsuranceappraiser.com/insurance-appraisal-questions/#breadcrumb"},{"@type":"FAQPage","mainEntity":[{"@type":"Question","name":"What is insurance appraisal?","acceptedAnswer":{"@type":"Answer","text":"Appraisal is a process written into most property policies for settling disagreements about the amount of a loss. Each side picks an appraiser, the appraisers pick an umpire, and a written award signed by any two of the three sets the amount."}},{"@type":"Question","name":"Is appraisal the same as arbitration?","acceptedAnswer":{"@type":"Answer","text":"They are similar but not identical. Appraisal is usually limited to the amount of loss and is less formal, with no hearings or discovery in most cases. How a Kentucky court treats an appraisal award is a legal question for an attorney."}},{"@type":"Question","name":"What kinds of disputes fit appraisal?","acceptedAnswer":{"@type":"Answer","text":"Disputes over repair scope, pricing, quantities, matching, overhead and profit, and contents values are the most common. Disputes over whether a loss is covered at all generally do not fit."}},{"@type":"Question","name":"Who can demand appraisal?","acceptedAnswer":{"@type":"Answer","text":"Most policies let either the policyholder or the insurer demand appraisal in writing once the two sides disagree on the amount of loss. Your policy controls the exact wording."}},{"@type":"Question","name":"Is the award binding?","acceptedAnswer":{"@type":"Answer","text":"Most policies say the award sets the amount of loss when two of the three sign it. Courts may set aside an award in limited situations, such as fraud or an appraiser who exceeded their authority, which is a question for a Kentucky attorney."}},{"@type":"Question","name":"Who pays for appraisal?","acceptedAnswer":{"@type":"Answer","text":"Most policies say each side pays its own appraiser and the two sides split the umpire and other shared costs equally. Read your clause, because some policies word this differently."}},{"@type":"Question","name":"How are party appraisers paid?","acceptedAnswer":{"@type":"Answer","text":"Fee structures include hourly, flat-fee and percentage arrangements. Ask for the fee in writing before you sign anything and ask whether the structure affects impartiality under your policy."}},{"@type":"Question","name":"How much does an umpire cost?","acceptedAnswer":{"@type":"Answer","text":"Umpires usually bill hourly, and the total depends on how many items are disputed and whether they inspect the property. Your share is typically half."}},{"@type":"Question","name":"Is appraisal worth it for a small gap?","acceptedAnswer":{"@type":"Answer","text":"Often not. If the difference between estimates is only a few thousand dollars, appraisal fees may eat most of any gain. Our payoff estimator can help you compare."}},{"@type":"Question","name":"How long does appraisal take?","acceptedAnswer":{"@type":"Answer","text":"Simple residential appraisals can wrap up in a few weeks, while large commercial or contested claims can take several months. Scheduling the umpire and inspections is usually the biggest variable."}},{"@type":"Question","name":"How soon must I name my appraiser?","acceptedAnswer":{"@type":"Answer","text":"Many policies give each side about 20 days after the written demand. Check your clause, because the window varies."}},{"@type":"Question","name":"Does appraisal stop the deadline to sue?","acceptedAnswer":{"@type":"Answer","text":"Not necessarily. Policies set a suit limitation period, Kentucky law limits how short it can be, and appraisal may not pause it. Read the policy and talk to a Kentucky attorney if the date is near."}},{"@type":"Question","name":"Can I demand appraisal after cashing a check?","acceptedAnswer":{"@type":"Answer","text":"Usually yes, if the insurer paid an undisputed amount and you still disagree about the total. Be careful with any release language, and get legal advice if a payment is labeled final."}},{"@type":"Question","name":"When should I demand appraisal?","acceptedAnswer":{"@type":"Answer","text":"After you have a solid competing estimate, the insurer has had a fair chance to review it, and talks have stalled. Demanding too early, before the scope is documented, can backfire."}},{"@type":"Question","name":"Who regulates insurers in Kentucky?","acceptedAnswer":{"@type":"Answer","text":"The Kentucky Department of Insurance in Frankfort, part of the Public Protection Cabinet. It accepts consumer complaints about claim handling."}},{"@type":"Question","name":"Does Kentucky law require insurers to offer appraisal?","acceptedAnswer":{"@type":"Answer","text":"Appraisal rights come from the policy itself. Most Kentucky property policies include an appraisal clause, but the wording varies, so read yours."}},{"@type":"Question","name":"What if my insurer is the Kentucky FAIR Plan?","acceptedAnswer":{"@type":"Answer","text":"The Kentucky FAIR Plan is the property insurer of last resort. Its policy forms have their own conditions, so check whether yours includes appraisal and how it reads."}},{"@type":"Question","name":"Do you work outside Louisville and Lexington?","acceptedAnswer":{"@type":"Answer","text":"Yes. We serve all 120 Kentucky counties, from Paducah and Hopkinsville in the west to Pikeville and Ashland in the east."}},{"@type":"Question","name":"Can appraisal resolve a bad-faith claim?","acceptedAnswer":{"@type":"Answer","text":"No. Appraisal sets the amount of loss only. Questions about claims handling under Kentucky’s Unfair Claims Settlement Practices Act belong with a Kentucky attorney."}},{"@type":"Question","name":"Are you a public adjuster or a law firm?","acceptedAnswer":{"@type":"Answer","text":"Neither. We are independent appraisers who handle appraisal representation, estimate review and umpire work. We do not give legal advice or negotiate coverage."}},{"@type":"Question","name":"Do you work for insurers as well as owners?","acceptedAnswer":{"@type":"Answer","text":"We may serve as a party appraiser for either side or as a neutral umpire. We disclose relationships that bear on impartiality before accepting an assignment."}},{"@type":"Question","name":"What do you need to review my claim?","acceptedAnswer":{"@type":"Answer","text":"The full policy with declarations and endorsements, the insurer’s estimate, any contractor bids, photos and the key correspondence. A summary of the timeline helps too."}},{"@type":"Question","name":"Can you review an estimate without starting appraisal?","acceptedAnswer":{"@type":"Answer","text":"Yes. A second-look estimate review can show where the numbers differ and whether appraisal is likely to be worth it."}},{"@type":"Question","name":"How do I get started?","acceptedAnswer":{"@type":"Answer","text":"Use the contact page to send a short description of the loss and the dispute. We will tell you honestly whether appraisal appears to fit."}}],"@id":"https://kentuckyinsuranceappraiser.com/insurance-appraisal-questions/#faq"}]}</script>
</head>
